# FR : ⚠️ AJOUT (13/10/2026, v0.4.3) - TEST D'INTERFACE de la FORGE, vue « Collection » des armes (VRAI composant, faux Manifest d'armes, fausse API Bungie pour les collections). Depuis la racine du projet : python3 tests/ui/forge.py  (construit la page lui-même).
import glob, os, re, subprocess, sys
from playwright.sync_api import sync_playwright
racine = os.getcwd()
if subprocess.run(["node", "tests/ui/build.mjs", "forge"], capture_output=True).returncode != 0: print("❌ construction de la page impossible"); sys.exit(1)
chrome = os.environ.get("CHROME_PATH") or next(iter(sorted(glob.glob(os.path.expanduser("~/.cache/puppeteer/chrome/*/chrome-linux64/chrome")))), None)
res = []
def ok(nom, cond, detail=""):
    res.append(bool(cond)); print(("✅" if cond else "❌"), nom, ("— " + str(detail)[:400]) if (detail and not cond) else "")
URL = "file://" + racine + "/tests/ui/_sortie/forge.html"
with sync_playwright() as p:
    b = p.chromium.launch(executable_path=chrome) if chrome else p.chromium.launch()
    erreurs = []
    def ouvrir(variante=""):
        pg = b.new_page(viewport={"width": 1280, "height": 900})
        pg.on("pageerror", lambda e: erreurs.append(str(e))); pg.on("console", lambda m: erreurs.append(m.text) if m.type == "error" else None)
        # FR : les icônes des armes d'essai pointent vers www.bungie.net (pas d'accès Internet ici) : on répond par une image minimale, comme le ferait Bungie, pour que la console ne signale que de VRAIES erreurs de l'appli.
        PNG = bytes.fromhex("89504e470d0a1a0a0000000d49484452000000010000000108060000001f15c4890000000d49444154789c6360f8cfc0f01f0005000201a5f645400000000049454e44ae426082")
        pg.route("**/www.bungie.net/**", lambda r: r.fulfill(status=200, content_type="image/png", body=PNG))
        pg.goto(URL + variante); pg.wait_for_function("window.__pret===true"); pg.wait_for_timeout(500)
        return pg
    noms = lambda pg: pg.evaluate("[...document.querySelectorAll('[data-arme] strong')].map(e => e.textContent)")
    compteur = lambda pg: pg.locator("[data-compteur]").inner_text()
    pg = ouvrir()
    # ---------- 1. liste par défaut ----------
    ok("la page Forge s'ouvre sur la vue « Collection » (onglet sélectionné) et la lecture des armes du Manifest aboutit", pg.get_by_role("tab", name="Collection").get_attribute("aria-selected") == "true" and pg.locator("[data-arme]").count() > 0)
    ok("par défaut, SEULES les armes des Collections du jeu sont listées (2) : l'arme sans collection est mise de côté ; les armes masquées, l'armure, l'objet sans nom et l'objet factice n'apparaissent jamais", noms(pg) == ["Fusil d'essai", "Lance-roquettes d'essai"] and compteur(pg).startswith("2 armes"), [noms(pg), compteur(pg)])
    # ---------- 2. couleurs / grisé ----------
    st = lambda h: pg.evaluate("h => { const e = document.querySelector('[data-arme=\"'+h+'\"]'); const s = getComputedStyle(e); return { o: e.dataset.obtention, op: s.opacity, f: s.filter, t: e.textContent }; }", h)
    s1, s2 = st(5001), st(5002)
    ok("COMME DANS LE JEU : l'arme OBTENUE est en couleurs normales (opacité 1, aucun filtre)", s1["o"] == "obtenu" and s1["op"] == "1" and s1["f"] == "none" and "Jamais obtenue" not in s1["t"], s1)
    ok("COMME DANS LE JEU : l'arme JAMAIS OBTENUE est GRISÉE (opacité réduite, niveaux de gris) ; la mention « Jamais obtenue » est RETIRÉE (demande de l'utilisateur du 13/10/2026 : redondante avec l'effet grisé, qui reste porté par data-obtention)", s2["o"] == "jamais" and float(s2["op"]) < 0.6 and "grayscale" in s2["f"] and "Jamais obtenue" not in s2["t"], s2)
    ok("le bandeau annonce que les collections du compte ont été lues", pg.locator("[data-collections]").get_attribute("data-collections") == "lues")
    # ---------- 2 bis. cartes : les quatre icônes (v0.4.4, demande de l'utilisateur) ----------
    icones = lambda h: pg.evaluate("h => [...document.querySelector('[data-arme=\"'+h+'\"]').querySelectorAll('[data-icones-arme] > [data-icone]')].map(x => x.dataset.icone + (x.querySelector('svg,img') ? '' : '(vide)'))", h)
    carte = lambda h: pg.evaluate("h => { const e = document.querySelector('[data-arme=\"'+h+'\"]'); const m = e.querySelector('[data-icones-arme] > span:last-child'); return { texte: e.innerText, armature: e.querySelector('[data-armature]')?.textContent ?? null, masqueLargeur: m ? m.getBoundingClientRect().width : null, masqueTexte: m ? m.textContent : null }; }", h)
    ok("CARTES : les QUATRE icônes dans l'ordre demandé, type d'arme, élément de dégâts, munitions, antichampion (le Fusil d'essai en a les quatre, aucune n'est vide)", icones(5001) == ["type", "element", "munition", "champion"], icones(5001))
    ok("CARTES : une arme sans antichampion (le Lance-roquettes exotique) n'affiche que TROIS icônes : type, élément, munitions", icones(5002) == ["type", "element", "munition"], icones(5002))
    c1, c2 = carte(5001), carte(5002)
    ok("CARTES : l'ARMATURE reste affichée en texte sur chaque carte", c1["armature"] == "Armature adaptative" and c2["armature"] == "Œil d'essai", [c1["armature"], c2["armature"]])
    ok("CARTES : les mots « type · emplacement · élément » ne sont plus affichés (aucun séparateur « · »), mais un texte caché pour les lecteurs d'écran les redit (type, emplacement, élément, antichampion) : accessibilité conservée", " · " not in c1["texte"] and c1["masqueLargeur"] <= 1 and "Fusil à impulsion" in c1["masqueTexte"] and "Énergétique" in c1["masqueTexte"] and "anti-Bloqueur" in c1["masqueTexte"] and "Lourde" in c2["masqueTexte"], [c1, c2])
