    ok("BOUTONS : même hauteur (44 px) et largeur = 4316 / 1024 de la hauteur (cadre commun des boutons du sélecteur : aucun décalage de mise en page)", all(o["h"] == 44 and abs(o["l"] - 44 * 4316 / 1024) < 1.5 for o in ong), [(o["h"], o["l"]) for o in ong])
    ok("BOUTONS : à l'ouverture, « Collection » est sélectionné (image sélectionnée visible, image de repos masquée) et « Inventaire » au repos (l'inverse)", ong[0]["sel"] == "true" and ong[0]["img"]["actif"][0] == "1" and ong[0]["img"]["repos"][0] == "0" and ong[1]["sel"] == "false" and ong[1]["img"]["actif"][0] == "0" and ong[1]["img"]["repos"][0] == "1", ong)
    pg.evaluate("document.activeElement && document.activeElement.blur()")
    for _ in range(12):
        pg.keyboard.press("Tab")
        if pg.evaluate("document.activeElement?.dataset?.sousMenu ?? ''") == "collection": break
    anneau = pg.evaluate("(() => { const s = getComputedStyle(document.activeElement); return [s.outlineStyle, s.outlineWidth]; })()")
    ok("BOUTONS : au CLAVIER (touche Tab), le bouton prend l'anneau de focus visible du sélecteur (contour plein de 2 px)", anneau == ["solid", "2px"], anneau)
    pg.keyboard.press("Tab"); pg.keyboard.press("Enter"); pg.wait_for_timeout(350)   # ⚠️ on attend la fin du fondu (0,15 s) avant de lire les opacités
    ong2 = pg.evaluate(ETAT_ONGLETS)
    ok("BOUTONS : « Tab » puis « Entrée » sélectionne « Inventaire » : les rôles s'inversent (sélectionné / repos) sans changer de taille", ong2[1]["sel"] == "true" and ong2[1]["img"]["actif"][0] == "1" and ong2[0]["sel"] == "false" and ong2[0]["img"]["repos"][0] == "1" and ong2[0]["h"] == 44 and ong2[1]["h"] == 44 and pg.get_by_role("tabpanel", name="Inventaire").is_visible(), ong2)
    pg.keyboard.press("Shift+Tab"); pg.keyboard.press("Enter"); pg.wait_for_timeout(350)
    # ---------- 3. source ----------
    pg.get_by_label("Source").select_option("tout"); pg.wait_for_timeout(100)
