    ok("source « Tout » : l'arme hors Collections apparaît, EN COULEURS (son état est inconnaissable : jamais grisée à tort) avec la mention « Hors Collections du jeu »", len(noms(pg)) == 3 and s3["o"] == "inconnu" and s3["op"] == "1" and "Hors Collections du jeu" in s3["t"], [noms(pg), s3])
